#!/usr/bin/env node
/* Regenerates js/data/bundled.js from the CSV files in data/.
 * Bundling the CSVs as JS strings lets index.html work when opened directly from disk (file://),
 * where browsers block fetch() of local files.
 * Usage: node tools/bundle-data.js */
'use strict';
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const FILES = [
  { file: 'nifty_pcr_maxpain.csv', origin: 'Original project export (user data pipeline; underlying source: NSE end-of-day F&O data and India VIX). Not independently verified by this application.' },
  { file: 'nifty_strike_oi.csv', origin: 'Original project export, latest five sessions only (user data pipeline; underlying source: NSE end-of-day F&O data). Import the full file for complete strike history.' }
];

const generated = new Date().toISOString();
const items = FILES.map(f => {
  const text = fs.readFileSync(path.join(ROOT, 'data', f.file), 'utf8');
  return { file: f.file, origin: f.origin, generated, text };
});

const out = '/* AUTO-GENERATED by tools/bundle-data.js — do not edit by hand. */\n' +
  '(function (root) { root.NRP = root.NRP || {}; root.NRP.BUNDLED = ' + JSON.stringify(items) + '; })(typeof self !== "undefined" ? self : this);\n';
fs.writeFileSync(path.join(ROOT, 'js', 'data', 'bundled.js'), out);
console.log(`Wrote js/data/bundled.js (${items.map(i => `${i.file}: ${i.text.split('\n').length - 2} rows`).join(', ')})`);
